constraints:
1 ≤ N ≤ 10^{5}
1 ≤ arr[i] ≤ 10^{5}

expected time complexity: O(n)
expected auxiliary space: O(n)

standard_solution_code:
class Solution:

	def binarySearchable(self, Arr, n):
		left = [0] * n
		right = [100000] * n
		left[0] = Arr[0]
		for i in range(1, n):
			left[i] = max(left[i - 1], Arr[i])
		right[n - 1] = Arr[n - 1]
		for i in range(n - 2, -1, -1):
			right[i] = min(right[i + 1], Arr[i])
		ans = 0
		for i in range(n):
			if i == 0 and right[1] > Arr[i]:
				ans += 1
			elif i == n - 1 and left[n - 2] < Arr[n - 1]:
				ans += 1
			elif left[i - 1] < Arr[i] < right[i + 1]:
				ans += 1
		return ans
